import "server-only";
import { sqlClient } from "./db";
import { getMotmWinner } from "./motm";
import { getRecentForm } from "./home";
import type { RatingChange } from "./score-snapshots";
import {
  MAX_MOMENTS_PER_OPEN,
  sortMoments,
  type Moment,
  type MomentKind,
} from "./moment-copy";

/**
 * "Moments": celebrations (and the odd light-hearted bummer) generated by
 * server events and shown once, the next time the player opens the app.
 * Stored in player_moments, unique per (player, kind, match) so generators are
 * idempotent. Nothing here may block the event that triggered it.
 */

const MOMENT_TTL_DAYS = 14;
const BUMMER_COOLDOWN_DAYS = 14;
const GAME_MILESTONES = [10, 25, 50, 75, 100, 150, 200];
const GOAL_MILESTONES = [10, 25, 50, 100, 150, 200, 300];
const STREAK_MILESTONES = [3, 5, 7, 10];

type NewMoment = {
  playerId: number;
  kind: MomentKind;
  matchId: number;
  payload: Record<string, unknown>;
};

/** Insert many moments in one round trip; existing ones are left untouched. */
export async function addMoments(list: NewMoment[]): Promise<void> {
  if (list.length === 0) return;
  await sqlClient.query(
    `INSERT INTO player_moments (player_id, kind, match_id, payload)
     SELECT t.p, t.k, t.m, t.j::jsonb
       FROM unnest($1::int[], $2::text[], $3::int[], $4::text[]) AS t(p, k, m, j)
     ON CONFLICT (player_id, kind, match_id) DO NOTHING`,
    [
      list.map((m) => m.playerId),
      list.map((m) => m.kind),
      list.map((m) => m.matchId),
      list.map((m) => JSON.stringify(m.payload)),
    ],
  );
}

/** Kudos pile up into one unseen moment ("A, B and C gave you kudos"). */
export async function addKudosMoment(toPlayerId: number, fromName: string): Promise<void> {
  await sqlClient.query(
    `INSERT INTO player_moments (player_id, kind, match_id, payload)
     VALUES ($1, 'kudos', 0, jsonb_build_object('from', jsonb_build_array($2::text)))
     ON CONFLICT (player_id, kind, match_id) DO UPDATE SET
       payload = CASE
         WHEN player_moments.seen_at IS NULL
           THEN jsonb_build_object('from', COALESCE(player_moments.payload->'from', '[]'::jsonb) || EXCLUDED.payload->'from')
         ELSE EXCLUDED.payload END,
       created_at = now(),
       seen_at = NULL`,
    [toPlayerId, fromName],
  );
}

/** Up to MAX_MOMENTS_PER_OPEN unseen, recent moments, most exciting first. */
export async function getUnseenMoments(playerId: number): Promise<Moment[]> {
  const rows = (await sqlClient.query(
    `SELECT id, kind, match_id, payload, created_at
       FROM player_moments
      WHERE player_id = $1 AND seen_at IS NULL
        AND created_at > now() - make_interval(days => $2::int)
      ORDER BY created_at DESC
      LIMIT 20`,
    [playerId, MOMENT_TTL_DAYS],
  )) as Array<{ id: number; kind: MomentKind; match_id: number; payload: Record<string, unknown>; created_at: string }>;
  const list: Moment[] = rows.map((r) => ({
    id: Number(r.id),
    kind: r.kind,
    matchId: Number(r.match_id),
    payload: r.payload ?? {},
    createdAt: String(r.created_at),
  }));
  return sortMoments(list).slice(0, MAX_MOMENTS_PER_OPEN);
}

export async function markMomentsSeen(playerId: number, ids: number[]): Promise<void> {
  if (ids.length === 0) return;
  await sqlClient.query(
    `UPDATE player_moments SET seen_at = now()
      WHERE player_id = $1 AND id = ANY($2::int[]) AND seen_at IS NULL`,
    [playerId, ids],
  );
}

export type RosterRow = {
  player_id: number;
  name: string;
  team_no: number;
  pos: string;
  fun_messages: boolean;
  goals: number;
  assists: number;
  w: number;
  l: number;
  d: number;
  cs: number;
  rounds: number;
  apps: number;
  career_goals: number;
  own_goals: number;
  last3_goals: number;
};

export async function getMatchRosterFacts(matchId: number): Promise<RosterRow[]> {
  const rows = (await sqlClient.query(
    `WITH r AS (
       SELECT mr.id, mr.team_a, mr.team_b,
              COALESCE(SUM(CASE WHEN rg.team_no = mr.team_a THEN 1 ELSE 0 END), 0) AS a,
              COALESCE(SUM(CASE WHEN rg.team_no = mr.team_b THEN 1 ELSE 0 END), 0) AS b
         FROM match_rounds mr
         LEFT JOIN round_goals rg ON rg.round_id = mr.id
        WHERE mr.match_id = $1 AND mr.status = 'done'
        GROUP BY mr.id, mr.team_a, mr.team_b
     ),
     sides AS (
       SELECT team_a AS team_no, a AS gf, b AS ga FROM r
       UNION ALL
       SELECT team_b, b, a FROM r
     ),
     t AS (
       SELECT team_no,
              SUM(CASE WHEN gf > ga THEN 1 ELSE 0 END) AS w,
              SUM(CASE WHEN gf < ga THEN 1 ELSE 0 END) AS l,
              SUM(CASE WHEN gf = ga THEN 1 ELSE 0 END) AS d,
              SUM(CASE WHEN ga = 0 THEN 1 ELSE 0 END) AS cs,
              COUNT(*) AS rounds
         FROM sides GROUP BY team_no
     )
     SELECT mp.player_id, p.name, mp.team_no,
            UPPER(COALESCE(NULLIF(mp.position_played, ''), p.preferred_position)) AS pos,
            COALESCE(p.fun_messages, true) AS fun_messages,
            COALESCE(s.goals, 0) AS goals, COALESCE(s.assists, 0) AS assists,
            COALESCE(t.w, 0) AS w, COALESCE(t.l, 0) AS l, COALESCE(t.d, 0) AS d,
            COALESCE(t.cs, 0) AS cs, COALESCE(t.rounds, 0) AS rounds,
            (SELECT COUNT(*) FROM match_players mp2
               JOIN matches m2 ON m2.id = mp2.match_id AND m2.matchday_status = 'closed'
              WHERE mp2.player_id = mp.player_id) AS apps,
            (SELECT COALESCE(SUM(s2.goals), 0) FROM stats s2
               JOIN matches m2 ON m2.id = s2.match_id AND m2.matchday_status = 'closed'
              WHERE s2.player_id = mp.player_id) AS career_goals,
            (SELECT COUNT(*) FROM round_goals rg
              WHERE rg.match_id = $1 AND rg.scorer_player_id = mp.player_id AND COALESCE(rg.is_own_goal, 0) <> 0) AS own_goals,
            (SELECT COALESCE(SUM(s3.goals), 0)
               FROM (SELECT m3.id FROM match_players mp3
                       JOIN matches m3 ON m3.id = mp3.match_id AND m3.matchday_status = 'closed'
                      WHERE mp3.player_id = mp.player_id
                      ORDER BY m3.played_on DESC, m3.id DESC LIMIT 3) last3
               LEFT JOIN stats s3 ON s3.match_id = last3.id AND s3.player_id = mp.player_id) AS last3_goals
       FROM match_players mp
       JOIN players p ON p.id = mp.player_id
       LEFT JOIN stats s ON s.match_id = mp.match_id AND s.player_id = mp.player_id
       LEFT JOIN t ON t.team_no = mp.team_no
      WHERE mp.match_id = $1`,
    [matchId],
  )) as Array<Record<string, unknown>>;
  return rows.map((r) => ({
    player_id: Number(r.player_id),
    name: String(r.name),
    team_no: Number(r.team_no),
    pos: String(r.pos ?? ""),
    fun_messages: r.fun_messages !== false,
    goals: Number(r.goals),
    assists: Number(r.assists),
    w: Number(r.w),
    l: Number(r.l),
    d: Number(r.d),
    cs: Number(r.cs),
    rounds: Number(r.rounds),
    apps: Number(r.apps),
    career_goals: Number(r.career_goals),
    own_goals: Number(r.own_goals),
    last3_goals: Number(r.last3_goals),
  }));
}

function crossed(milestones: number[], before: number, after: number): number | null {
  let hit: number | null = null;
  for (const m of milestones) if (before < m && after >= m) hit = m;
  return hit;
}

/** Players who already had a bummer recently (we cap them at one per 14 days). */
async function recentBummerPlayers(): Promise<Set<number>> {
  const rows = (await sqlClient.query(
    `SELECT DISTINCT player_id FROM player_moments
      WHERE kind LIKE 'bummer\\_%' AND created_at > now() - make_interval(days => $1::int)`,
    [BUMMER_COOLDOWN_DAYS],
  )) as Array<{ player_id: number }>;
  return new Set(rows.map((r) => Number(r.player_id)));
}

/**
 * Called on matchday close. Builds every celebration for the roster and, for
 * players who got none, at most one gentle bummer with a silver lining.
 */
export async function generateMatchMoments(
  matchId: number,
  ctx: {
    changes: RatingChange[];
    unlocked: Array<{ playerId: number; label: string }>;
  },
): Promise<number> {
  const [roster, motm, bummerCooldown] = await Promise.all([
    getMatchRosterFacts(matchId),
    getMotmWinner(matchId),
    recentBummerPlayers(),
  ]);
  if (roster.length === 0) return 0;

  const out: NewMoment[] = [];
  const add = (playerId: number, kind: MomentKind, payload: Record<string, unknown> = {}) =>
    out.push({ playerId, kind, matchId, payload });

  const changeBy = new Map(ctx.changes.map((c) => [c.playerId, c]));
  const maxGoals = Math.max(0, ...roster.map((r) => r.goals));

  const badgesBy = new Map<number, string[]>();
  for (const u of ctx.unlocked) {
    if (!badgesBy.has(u.playerId)) badgesBy.set(u.playerId, []);
    badgesBy.get(u.playerId)!.push(u.label);
  }

  const forms = await Promise.all(roster.map((r) => getRecentForm(r.player_id, 10)));

  roster.forEach((r, i) => {
    const id = r.player_id;
    if (motm && motm.playerId === id && motm.votes > 0) add(id, "motm", { votes: motm.votes });
    if (r.goals >= 3) add(id, "hat_trick", { goals: r.goals });
    else if (r.goals >= 2 && r.goals === maxGoals) add(id, "top_scorer", { goals: r.goals });

    const c = changeBy.get(id);
    if (c) {
      if (c.newRank === 1 && c.prevRank !== 1) add(id, "number_one", { newRank: 1 });
      else if (c.newRank <= 5 && c.prevRank > 5) add(id, "top5", { newRank: c.newRank });
      else if (c.deltaRank >= 3) add(id, "rank_up", { places: c.deltaRank, newRank: c.newRank });
    }

    const badges = badgesBy.get(id);
    if (badges?.length) add(id, "badge", { badges });

    if (r.rounds >= 2) {
      if ((r.pos === "GK" || r.pos === "DEF") && r.cs > 0) add(id, "clean_sheet", { rounds: r.cs });
      if (r.l === 0 && r.w > 0) add(id, "unbeaten", { w: r.w, d: r.d });
    }

    let streak = 0;
    for (const f of forms[i]) {
      if (f.result !== "W") break;
      streak++;
    }
    if (forms[i][0]?.matchId === matchId && STREAK_MILESTONES.includes(streak)) {
      add(id, "win_streak", { count: streak });
    }

    const games = crossed(GAME_MILESTONES, r.apps - 1, r.apps);
    if (games) add(id, "milestone_games", { count: games });
    const goals = crossed(GOAL_MILESTONES, r.career_goals - r.goals, r.career_goals);
    if (goals) add(id, "milestone_goals", { count: goals });
  });

  // Bummers: private, opt-out, only when nothing good happened, max 1 / 14 days.
  const celebrated = new Set(out.map((m) => m.playerId));
  for (const r of roster) {
    if (!r.fun_messages || celebrated.has(r.player_id) || bummerCooldown.has(r.player_id)) continue;
    const silverLining =
      r.assists > 0
        ? `Silver lining: you still set up ${r.assists} goal${r.assists === 1 ? "" : "s"}.`
        : r.goals > 0
          ? `Silver lining: you still found the net ${r.goals === 1 ? "once" : `${r.goals} times`}.`
          : r.cs > 0
            ? "Silver lining: your team still kept a clean sheet."
            : "Silver lining: you showed up. That's half the game.";
    const c = changeBy.get(r.player_id);
    if (r.rounds >= 2 && r.w === 0 && r.l >= 2) {
      add(r.player_id, "bummer_winless", { l: r.l, silverLining });
    } else if (r.own_goals > 0) {
      add(r.player_id, "bummer_own_goal", { count: r.own_goals, silverLining });
    } else if (c && c.deltaFinal <= -0.5) {
      add(r.player_id, "bummer_rating_drop", { newFinal: c.newFinal, silverLining });
    } else if (r.pos === "FWD" && r.apps >= 3 && r.last3_goals === 0) {
      add(r.player_id, "bummer_scoreless", { silverLining });
    }
  }

  await addMoments(out);
  return out.length;
}

/**
 * "Publish teams": tell each rostered player which team they're on, with
 * teammates. Returns the number of players notified.
 */
export async function generateTeamRevealMoments(matchId: number): Promise<number[]> {
  const rows = (await sqlClient.query(
    `SELECT mp.player_id, mp.team_no, p.name, m.team_names
       FROM match_players mp
       JOIN players p ON p.id = mp.player_id
       JOIN matches m ON m.id = mp.match_id
      WHERE mp.match_id = $1 AND mp.team_no IS NOT NULL AND mp.team_no > 0`,
    [matchId],
  )) as Array<{ player_id: number; team_no: number; name: string; team_names: string | null }>;
  if (rows.length === 0) return [];
  let names: Record<string, string> = {};
  const rawNames: unknown = rows[0].team_names;
  try {
    if (typeof rawNames === "string" && rawNames.trim()) names = JSON.parse(rawNames) as Record<string, string>;
    else if (rawNames && typeof rawNames === "object") names = rawNames as Record<string, string>;
  } catch {
    names = {};
  }
  const byTeam = new Map<number, typeof rows>();
  for (const r of rows) {
    const t = Number(r.team_no);
    if (!byTeam.has(t)) byTeam.set(t, []);
    byTeam.get(t)!.push(r);
  }
  const list: NewMoment[] = rows.map((r) => {
    const t = Number(r.team_no);
    return {
      playerId: Number(r.player_id),
      kind: "team_reveal",
      matchId,
      payload: {
        teamNo: t,
        teamName: names[String(t)]?.trim() || `Team ${t}`,
        teammates: byTeam
          .get(t)!
          .filter((x) => x.player_id !== r.player_id)
          .map((x) => String(x.name).split(" ")[0]),
      },
    };
  });
  // Re-publishing after a re-draft should re-reveal: replace unseen-or-seen rows.
  await sqlClient.query(`DELETE FROM player_moments WHERE match_id = $1 AND kind = 'team_reveal'`, [matchId]);
  await addMoments(list);
  return list.map((m) => m.playerId);
}

/** Player's opt-in for light-hearted bummer messages (default on). */
export async function getFunMessages(playerId: number): Promise<boolean> {
  const rows = (await sqlClient.query(`SELECT fun_messages FROM players WHERE id = $1`, [playerId])) as Array<{
    fun_messages: boolean | null;
  }>;
  return rows[0]?.fun_messages !== false;
}

export async function setFunMessages(playerId: number, enabled: boolean): Promise<void> {
  await sqlClient.query(`UPDATE players SET fun_messages = $2 WHERE id = $1`, [playerId, enabled]);
}

/** When the teams were last published for a match (null = never). */
export async function getTeamsPublishedAt(matchId: number): Promise<string | null> {
  const rows = (await sqlClient.query(
    `SELECT MAX(created_at) AS at FROM player_moments WHERE match_id = $1 AND kind = 'team_reveal'`,
    [matchId],
  )) as Array<{ at: string | null }>;
  return rows[0]?.at ? String(rows[0].at) : null;
}
